// ensureNumSlotsEnv exports CLAB_IOL_NUM_SLOTS when the management interface is
// relocated, so that its slot exists even when no link lands in it.
func (n *iol) ensureNumSlotsEnv() {
	if n.mgmtLinuxIdx == 0 || n.Cfg.Env["CLAB_IOL_NUM_SLOTS"] != "" {
		return
	}

	intfIdxRegexp := regexp.MustCompile(`\d+`)
	needed := n.mgmtSlot + 1

	for _, ep := range n.EndpointsWithParked() {
		x, _ := strconv.Atoi(intfIdxRegexp.FindString(ep.GetIfaceName()))
		if slot, _ := n.iolPortForLinuxIdx(x); slot+1 > needed {
			needed = slot + 1
		}
	}

	n.Cfg.Env["CLAB_IOL_NUM_SLOTS"] = strconv.Itoa(needed)
}

func (n *iol) PreDeploy(ctx context.Context, params *clabnodes.PreDeployParams) error {
	clabutils.CreateDirectory(n.Cfg.LabDir, clabconstants.PermissionsOpen)

	if v := n.kindSpecificCfg().BootstrapConfig; v != "" {
		switch p := clabutils.ResolvePath(v, params.TopoPaths.TopologyFileDir()); {
		case strings.EqualFold(v, "none"):
			n.bootstrapNone = true
		case clabutils.FileExists(p):
			n.bootstrapCfgFile = p
		default:
			return fmt.Errorf("bootstrap-config file %q does not exist", p)
		}
	}

	_, err := n.LoadOrGenerateCertificate(params.Cert, params.TopologyName)
	if err != nil {
		return err
	}

	n.ensureNumSlotsEnv()

	return n.CreateIOLFiles(ctx)
}

func (n *iol) PostDeploy(ctx context.Context, _ *clabnodes.PostDeployParams) error {
	log.Infof("Running postdeploy actions for Cisco IOL '%s' node", n.Cfg.ShortName)

	n.disableMgmtTxOffload(ctx)

	if err := n.GenBootConfig(ctx); err != nil {
		return fmt.Errorf("failed to generate boot config: %w", err)
	}

	// Must update mgmt IP if not first boot, unless the node boots without a baseline config
	if !n.firstBoot && !n.bootstrapNone {
		return n.UpdateMgmtIntf(ctx)
	}

	return nil
}

// Start re-applies the mgmt veth TX offload fix after a stop/start cycle. The runtime
// recreates the mgmt veth (it is never parked), so its offload settings reset to defaults.
// See disableMgmtTxOffload for why IOL cannot function with it enabled.
func (n *iol) Start(ctx context.Context) error {
	if err := n.DefaultNode.Start(ctx); err != nil {
		return err
	}

	// DefaultNode.Start no-ops for root-ns and auto-remove nodes; skip the offload fix
	// for them as well, as there is no container mgmt veth to adjust.
	if n.ShouldSkipLifecycle() {
		return nil
	}

	n.disableMgmtTxOffload(ctx)

	return nil
}

// disableMgmtTxOffload disables TX checksum offload on the host NS veth for the mgmt interface.
// iouyap bridges IOL interfaces over packet sockets; frames carrying an offloaded
// (CHECKSUM_PARTIAL) checksum reach the IOL process with an incomplete checksum, which its
// TCP/IP stack drops, breaking TCP/UDP connectivity.
//
// Nodes running with host network mode are skipped: their eth0 is the host's interface,
// and there is no clab-created mgmt veth to adjust.
func (n *iol) disableMgmtTxOffload(ctx context.Context) {
	if n.Cfg.NetworkMode == "host" {
		return
	}

	if n.Runtime.Mgmt().Driver == clabtypes.MgmtDriverMacvlan {
		return
	}

	var peerIfIndex int
	err := n.ExecFunction(ctx, clabutils.VethPeerIndex("eth0", &peerIfIndex))
	if err != nil {
		log.Warn("Failed to get veth peer index for IOL mgmt interface",
			"node", n.Cfg.ShortName,
			"error", err)
		return
	}

	if err := clabutils.DisableTxOffloadByIndex(peerIfIndex); err != nil {
		log.Warn("Failed to disable TX checksum offload on IOL mgmt host veth",
			"node", n.Cfg.ShortName,
			"error", err)
	}
}

func (n *iol) CreateIOLFiles(ctx context.Context) error {
	// If NVRAM already exists, don't need to create
	// otherwise saved configs in NVRAM are overwritten.
	if !clabutils.FileExists(path.Join(n.Cfg.LabDir, n.nvramFile)) {
		// create nvram file
		clabutils.CreateFile(path.Join(n.Cfg.LabDir, n.nvramFile), "")
		n.firstBoot = true
	}
	// create these files so the bind monut doesn't automatically
	// make folders.
	if bootCfg := path.Join(n.Cfg.LabDir, "boot_config.txt"); !clabutils.FileExists(bootCfg) {
		clabutils.CreateFile(bootCfg, "")
	}

	return n.GenInterfaceConfig(ctx)
}

